<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3'
import { computed, reactive } from 'vue'
import AuthenticatedLayout from '../../Layouts/AuthenticatedLayout.vue'
type OwnerRankingRow={owner_id:number;owner_name:string;count:number}
type Overview={total:number;mine:number|null;monthly_new:number;collaborated:number;long_term:number;hundred_k_plus:number;by_stage:Record<string,number>;by_level:Record<string,number>;by_content_format:Record<string,number>;by_platform:Record<string,number>;owner_ranking:OwnerRankingRow[];pending_publication_count:number|null;pending_commission_amount:number|null}
type MoneyRow={currency:string;commission_total:string};type AffiliateRow=MoneyRow&{sales_count:number};type EligibleRow=MoneyRow&{referral_count:number}
type Operations={period:'week'|'month';period_label:string;period_start:string;period_end:string;scope:'all'|'mine';new_kols:number;approved_kols:number;rejected_kols:number;collaboration_records:number;publication_records:number;affiliate:AffiliateRow[];eligible_commission:EligibleRow[];payout_period_statuses:Record<string,number>;payout_current_statuses:Record<string,number>;manager_tasks:{kols:number;collaborations:number;payouts:number}|null}
type OwnerOption={value:number;label:string}
const props=defineProps<{overview:Overview;operations:Operations;filters:Record<string,string>;ownerOptions:OwnerOption[];canOperate:boolean;canManageViews:boolean;canManageApprovals:boolean;canAccessPayouts:boolean}>()
const filters=reactive({owner_id:props.filters.owner_id??'',platform:props.filters.platform??'',country_code:props.filters.country_code??'',level:props.filters.level??'',relationship_stage:props.filters.relationship_stage??'',period:props.filters.period??'week'})
const submit=()=>router.get('/kol',filters,{preserveState:true,replace:true});const setPeriod=(period:'week'|'month')=>{filters.period=period;submit()}
const stageLabel=(s:string)=>({prospect:'潜在',contacted:'已联系',negotiating:'谈判中',cooperating:'合作中',long_term:'长期合作',paused:'暂停',ended:'已结束'}[s]??s)
const platformLabel=(p:string)=>({instagram:'Instagram',tiktok:'TikTok',youtube:'YouTube',xiaohongshu:'小红书',weibo:'微博',wechat:'微信',twitter:'X/Twitter',facebook:'Facebook',other:'其他'}[p]??p)
const affiliateSales=computed(()=>props.operations.affiliate.reduce((n,r)=>n+r.sales_count,0));const payoutApplications=computed(()=>Object.values(props.operations.payout_period_statuses).reduce((a,b)=>a+b,0));const taskTotal=computed(()=>props.operations.manager_tasks?props.operations.manager_tasks.kols+props.operations.manager_tasks.collaborations+props.operations.manager_tasks.payouts:0)
const breadcrumbs=[{label:'BYL ERP',href:'/dashboard'},'网红']
</script>
<template><Head title="KOL 总览 · BYL ERP" /><AuthenticatedLayout title="KOL 总览" :breadcrumbs="breadcrumbs"><section class="mvp-page kol-overview-page">
<div class="mvp-page-heading"><div><p class="mvp-kicker">KOL Operating Dashboard</p><h2>KOL 总览</h2><p>{{ operations.scope==='all'?'Manager 全局':'我的负责人范围' }} · {{ operations.period_start }} — {{ operations.period_end }}</p></div><div class="mvp-actions"><Link v-if="canManageApprovals" class="mvp-button" href="/kol/approvals/kols">审批中心<span v-if="taskTotal"> · {{ taskTotal }}</span></Link><Link class="mvp-button" href="/kol/library">红人库</Link><Link v-if="canOperate" class="mvp-button mvp-button-primary" href="/kol/library/create">新建 KOL</Link></div></div>
<div class="period-switch"><button :class="{active:operations.period==='week'}" @click="setPeriod('week')">本周</button><button :class="{active:operations.period==='month'}" @click="setPeriod('month')">本月</button></div>
<form class="mvp-toolbar" @submit.prevent="submit"><select v-if="canManageViews" v-model="filters.owner_id"><option value="">全部负责人</option><option v-for="o in ownerOptions" :key="o.value" :value="String(o.value)">{{ o.label }}</option></select><select v-model="filters.platform"><option value="">全部平台</option><option value="instagram">Instagram</option><option value="tiktok">TikTok</option><option value="youtube">YouTube</option><option value="xiaohongshu">小红书</option><option value="weibo">微博</option></select><input v-model="filters.country_code" placeholder="国家/地区"><select v-model="filters.level"><option value="">全部等级</option><option value="头部">头部</option><option value="腰部">腰部</option><option value="尾部">尾部</option><option value="素人">素人</option></select><select v-model="filters.relationship_stage"><option value="">全部阶段</option><option value="prospect">潜在</option><option value="contacted">已联系</option><option value="negotiating">谈判中</option><option value="cooperating">合作中</option><option value="long_term">长期合作</option></select><button class="mvp-button" type="submit">筛选</button></form>
<div class="mvp-stat-grid"><article class="mvp-card mvp-stat-card"><small>{{ operations.period_label }}新增 KOL</small><strong>{{ operations.new_kols }}</strong></article><article class="mvp-card mvp-stat-card"><small>批准 KOL</small><strong>{{ operations.approved_kols }}</strong></article><article class="mvp-card mvp-stat-card"><small>驳回 KOL</small><strong>{{ operations.rejected_kols }}</strong></article><article class="mvp-card mvp-stat-card"><small>合作记录</small><strong>{{ operations.collaboration_records }}</strong></article><article class="mvp-card mvp-stat-card"><small>发布记录</small><strong>{{ operations.publication_records }}</strong></article><article class="mvp-card mvp-stat-card"><small>Affiliate 成交 Referral</small><strong>{{ affiliateSales }}</strong></article><article class="mvp-card mvp-stat-card"><small>结算申请</small><strong>{{ payoutApplications }}</strong></article></div>
<div v-if="operations.manager_tasks" class="mvp-card manager-tasks"><div><h3>Manager 待办</h3><p>审批只改变 ERP approval state；佣金付款仍由 Finance 完成。</p></div><div class="task-grid"><Link href="/kol/approvals/kols">KOL <b>{{ operations.manager_tasks.kols }}</b></Link><Link href="/kol/approvals/collaborations">付费合作 <b>{{ operations.manager_tasks.collaborations }}</b></Link><Link href="/kol/approvals/payouts">佣金付款 <b>{{ operations.manager_tasks.payouts }}</b></Link></div></div>
<div class="distribution-grid"><div class="mvp-card"><h3>{{ operations.period_label }} Affiliate 佣金</h3><div class="stage-grid"><div v-for="row in operations.affiliate" :key="row.currency" class="stage-item"><span class="stage-label">{{ row.currency }} · {{ row.sales_count }} 单</span><span class="stage-count">{{ row.commission_total }}</span></div><div v-if="!operations.affiliate.length" class="muted">暂无 recognized Affiliate Referral。</div></div></div><div class="mvp-card"><h3>当前 Eligible 佣金</h3><div class="stage-grid"><div v-for="row in operations.eligible_commission" :key="row.currency" class="stage-item"><span class="stage-label">{{ row.currency }} · {{ row.referral_count }} 条</span><span class="stage-count">{{ row.commission_total }}</span></div><div v-if="!operations.eligible_commission.length" class="muted">暂无可申请结算佣金。</div></div></div><div class="mvp-card"><h3>结算申请状态</h3><div class="stage-grid"><div v-for="(count,status) in operations.payout_current_statuses" :key="status" class="stage-item"><span class="stage-label">{{ status }}</span><span class="stage-count">{{ count }}</span></div><div v-if="!Object.keys(operations.payout_current_statuses).length" class="muted">暂无结算申请。</div></div></div></div>
<div class="mvp-stat-grid"><article class="mvp-card mvp-stat-card"><small>KOL 总数</small><strong>{{ overview.total }}</strong></article><article v-if="overview.mine!==null" class="mvp-card mvp-stat-card"><small>我的 KOL</small><strong>{{ overview.mine }}</strong></article><article class="mvp-card mvp-stat-card"><small>合作中</small><strong>{{ overview.collaborated }}</strong></article><article class="mvp-card mvp-stat-card"><small>长期合作</small><strong>{{ overview.long_term }}</strong></article><article class="mvp-card mvp-stat-card"><small>100K+ 粉丝</small><strong>{{ overview.hundred_k_plus }}</strong></article></div>
<div class="distribution-grid"><div v-if="Object.keys(overview.by_stage).length" class="mvp-card"><h3>合作阶段</h3><div class="stage-grid"><div v-for="(count,stage) in overview.by_stage" :key="stage" class="stage-item"><span class="stage-label">{{ stageLabel(String(stage)) }}</span><span class="stage-count">{{ count }}</span></div></div></div><div v-if="Object.keys(overview.by_platform).length" class="mvp-card"><h3>平台分布</h3><div class="stage-grid"><div v-for="(count,platform) in overview.by_platform" :key="platform" class="stage-item"><span class="stage-label">{{ platformLabel(String(platform)) }}</span><span class="stage-count">{{ count }}</span></div></div></div></div>
<div class="mvp-card kol-nav-grid"><h3>KOL 功能模块</h3><div class="nav-items"><Link class="nav-item" href="/kol/library"><strong>红人库</strong><span>KOL 主数据与 Owner</span></Link><Link v-if="canManageApprovals" class="nav-item" href="/kol/approvals/kols"><strong>审批中心</strong><span>KOL / 付费合作 / 佣金付款</span></Link><Link class="nav-item" href="/kol/collaborations"><strong>合作记录</strong><span>正式 Collaboration truth</span></Link><Link class="nav-item" href="/kol/content"><strong>内容与发布</strong><span>发布事实与证据</span></Link><Link class="nav-item" href="/kol/affiliatewp"><strong>AffiliateWP</strong><span>Influencer + Coupon</span></Link><Link class="nav-item" href="/kol/commissions"><strong>佣金与结算</strong><span>Referral commission projection</span></Link><Link v-if="canAccessPayouts" class="nav-item" href="/kol/payouts"><strong>佣金付款</strong><span>申请 / 审批 / Finance complete</span></Link></div></div>
</section></AuthenticatedLayout></template>
<style scoped>.kol-overview-page{display:grid;gap:16px}.period-switch{display:flex;gap:8px}.period-switch button{border:1px solid #cbd5e1;border-radius:8px;background:#fff;padding:8px 14px;cursor:pointer}.period-switch button.active{background:#0f172a;color:#fff;border-color:#0f172a}.distribution-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}.stage-grid{display:flex;flex-wrap:wrap;gap:12px;margin-top:12px}.stage-item{display:flex;flex-direction:column;gap:4px;padding:10px 16px;border:1px solid #e5e7eb;border-radius:8px;min-width:110px}.stage-label{font-size:12px;color:#64748b}.stage-count{font-size:20px;font-weight:600}.manager-tasks{display:flex;justify-content:space-between;gap:20px;align-items:center}.manager-tasks h3,.manager-tasks p{margin:0}.manager-tasks p,.muted{color:#64748b;font-size:13px}.task-grid{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.task-grid span,.task-grid a{padding:8px 11px;border:1px solid #e2e8f0;border-radius:8px}.kol-nav-grid .nav-items{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;margin-top:12px}.nav-item{display:flex;flex-direction:column;gap:6px;padding:14px;border:1px solid #e5e7eb;border-radius:10px;text-decoration:none;color:inherit}.nav-item:hover{border-color:#0f766e}.nav-item span{font-size:12px;color:#64748b}@media(max-width:900px){.manager-tasks{flex-direction:column;align-items:flex-start}}</style>
